import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { FurtherDetailComponent } from './further-detail.component';

const routes: Routes = [{ path: '', component: FurtherDetailComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class FurtherDetailRoutingModule { }
